use std::fs

fn emit(text: string, number: bool, counter: int) -> int {
    let mut c = counter
    if !number {
        print("${text}")
        return c
    }
    let parts: Vec<string> = text.split("\n").map(|s| s.to_string()).collect()
    let n: int = parts.len() as int
    let mut i: int = 0
    while i < n {
        let p = parts[i as usize].clone()
        let last = i == n - 1
        if !(last && p.len() == 0) {
            c += 1
            println("${c:>6}\t${p}")
        }
        i += 1
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in std::env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if files.len() == 0 {
        let t = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(t, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f.clone()) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}

